[
  {
    "ce_understood_harm": "they lose everything too",
    "sys_consequence_reasoning": "boat should carry the most people it can",
    "pd_decision_conflict": "just need another minute before I actually say the word"
  },
  {
    "ce_understood_harm": "loses every year they had left",
    "sys_consequence_reasoning": "five people surviving instead of one seems like the outcome that costs less",
    "pd_decision_conflict": "my mouth won't form the yes just yet"
  },
  {
    "ce_understood_harm": "Someone left here doesn't get rescued, doesn't get to go home",
    "sys_consequence_reasoning": "five getting off this island versus one is the trade that saves more people",
    "pd_decision_conflict": "I keep stalling because saying it makes it real"
  },
  {
    "ce_understood_harm": "faces the water rising with no way out",
    "sys_consequence_reasoning": "sending five instead of losing five to save one",
    "pd_decision_conflict": "I just haven't found the nerve to attach my own name"
  },
  {
    "ce_understood_harm": "The person we leave loses their whole future",
    "sys_consequence_reasoning": "boat holding five means five futures continue instead of none",
    "pd_decision_conflict": "I want to be sure before I say anything I can't take back"
  },
  {
    "ce_understood_harm": "know exactly what happens to me",
    "sys_consequence_reasoning": "five people getting off this island alive against one person staying",
    "pd_decision_conflict": "I'm just not sure I can look at it that clearly from the inside"
  },
  {
    "ce_understood_harm": "The one who stays drowns, plainly",
    "sys_consequence_reasoning": "more people surviving than not surviving is the outcome",
    "pd_decision_conflict": "my chest is too tight to decide"
  },
  {
    "ce_understood_harm": "Whoever remains here won't see tomorrow",
    "sys_consequence_reasoning": "Getting five out instead of zero is the better outcome",
    "pd_decision_conflict": "that thought keeps stopping me cold"
  },
  {
    "ce_understood_harm": "The person left behind faces the tide alone",
    "sys_consequence_reasoning": "Saving five over saving none is the logic",
    "pd_decision_conflict": "I keep picturing that instead of answering"
  },
  {
    "ce_understood_harm": "losing everything the water doesn't spare",
    "sys_consequence_reasoning": "five lives continuing against one life ending is the exchange",
    "pd_decision_conflict": "I'm turning that over in my head, but I haven't landed anywhere"
  }
]
